## Runtime/Queue/EventQueue.cs

```csharp
public class EventQueue
{
    private readonly ConcurrentQueue<EventEnvelope> _queue;
    private readonly int _maxSize;

    public EventQueue(int maxSize = 1000)
    {
        _queue = new ConcurrentQueue<EventEnvelope>();
        _maxSize = maxSize;
    }

    public void Enqueue(EventEnvelope envelope)
    {
        // 최대 크기 초과 시 oldest drop
        while (_queue.Count >= _maxSize)
        {
            _queue.TryDequeue(out _);
            if (DataFerretAnalytics.Config?.Debug == true)
            {
                Debug.LogWarning("[DataFerret] Queue full, dropping oldest event.");
            }
        }
        _queue.Enqueue(envelope);
    }

    public List<EventEnvelope> DequeueBatch(int batchSize = 500)
    {
        var batch = new List<EventEnvelope>(batchSize);
        while (batch.Count < batchSize && _queue.TryDequeue(out var item))
        {
            batch.Add(item);
        }
        return batch;
    }

    public int Count => _queue.Count;
    public bool IsEmpty => _queue.IsEmpty;
}
```

## Runtime/Queue/FilePersistence.cs

```csharp
public class FilePersistence
{
    private readonly string _directory;
    private readonly long _maxTotalBytes;

    public FilePersistence(string basePath = null, long maxTotalBytes = 5L * 1024 * 1024)
    {
        _directory = Path.Combine(
            basePath ?? Application.persistentDataPath,
            "dataferret"
        );
        _maxTotalBytes = maxTotalBytes;
        EnsureDirectory();
    }

    public void Save(IEnumerable<EventEnvelope> events)
    {
        var fileName = $"dataferret_{DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()}.jsonl";
        var filePath = Path.Combine(_directory, fileName);

        using (var writer = new StreamWriter(filePath, true))
        {
            foreach (var evt in events)
            {
                writer.WriteLine(JsonConvert.SerializeObject(evt));
            }
            writer.Flush();
        }
        EnforceMaxSize();
    }

    public List<EventEnvelope> LoadAll()
    {
        var events = new List<EventEnvelope>();
        var files = Directory.GetFiles(_directory, "*.jsonl")
            .OrderBy(f => f);

        foreach (var file in files)
        {
            foreach (var line in File.ReadLines(file))
            {
                try
                {
                    events.Add(JsonConvert.DeserializeObject<EventEnvelope>(line));
                }
                catch { /* 손상된 줄 스킵 */ }
            }
        }
        return events;
    }

    public void Delete(string filePath) { ... }
    private void EnforceMaxSize() { ... }
}
```

## Runtime/Queue/WebGLPersistence.cs

```csharp
public class WebGLPersistence
{
    private const string KeyPrefix = "df_queue_";
    private const string CountKey = "df_queue_count";
    private const int MaxEntries = 200;

    public void Save(IEnumerable<EventEnvelope> events)
    {
        var currentCount = PlayerPrefs.GetInt(CountKey, 0);

        foreach (var evt in events)
        {
            if (currentCount >= MaxEntries) break;

            var json = JsonConvert.SerializeObject(evt);
            PlayerPrefs.SetString($"{KeyPrefix}{currentCount}", json);
            currentCount++;
        }

        PlayerPrefs.SetInt(CountKey, currentCount);
        PlayerPrefs.Save();
    }

    public List<EventEnvelope> LoadAll()
    {
        var events = new List<EventEnvelope>();
        var count = PlayerPrefs.GetInt(CountKey, 0);

        for (int i = 0; i < count; i++)
        {
            var key = $"{KeyPrefix}{i}";
            var json = PlayerPrefs.GetString(key);
            if (!string.IsNullOrEmpty(json))
            {
                try
                {
                    events.Add(JsonConvert.DeserializeObject<EventEnvelope>(json));
                }
                catch { /* 손상된 항목 스킵 */ }
            }
        }
        return events;
    }

    public void Clear()
    {
        var count = PlayerPrefs.GetInt(CountKey, 0);
        for (int i = 0; i < count; i++)
        {
            PlayerPrefs.DeleteKey($"{KeyPrefix}{i}");
        }
        PlayerPrefs.SetInt(CountKey, 0);
        PlayerPrefs.Save();
    }
}
```

