   public static class WebGLCallbackRegistry
   {
       private static Dictionary<int, Action<int>> _callbacks = new();
       private static int _nextId = 0;

       public static int Register(Action<int> callback)
       {
           int id = _nextId++;
           _callbacks[id] = callback;
           return id;
       }

       [MonoPInvokeCallback(typeof(Action<int, int>))]
       public static void OnCallback(int callbackId, int result)
       {
           if (_callbacks.TryGetValue(callbackId, out var cb))
           {
               cb(result);
               _callbacks.Remove(callbackId);
           }
       }
   }
