```csharp
public class BuildProcessor : IPreprocessBuildWithReport
{
    public int callbackOrder => 0;

    public void OnPreprocessBuild(BuildReport report)
    {
        var config = LoadConfig();

        // Write Key 미설정 경고
        if (config == null || string.IsNullOrEmpty(config.WriteKey))
        {
            if (!EditorUtility.DisplayDialog(
                "DataFerret Analytics",
                "Write Key가 설정되지 않았습니다. 이벤트가 전송되지 않습니다.\n" +
                "Window > DataFerret Analytics에서 설정하세요.",
                "빌드 계속",
                "취소"))
            {
                throw new BuildFailedException("DataFerret Write Key 미설정");
            }
        }

        // Write Key 형식 검증
        if (config != null && !string.IsNullOrEmpty(config.WriteKey) && 
            !config.WriteKey.StartsWith("wk_"))
        {
            throw new BuildFailedException("DataFerret Write Key는 'wk_'로 시작해야 합니다.");
        }

        // Release 빌드 시 Debug 모드 비활성화
        if (!report.summary.options.HasFlag(BuildOptions.Development))
        {
            if (config != null && config.Debug)
            {
                Debug.LogWarning("[DataFerret] Release 빌드에서 Debug 모드가 비활성화됩니다.");
                config.Debug = false;
                SaveConfig(config);
            }
        }
    }
}
