private static readonly Stack<EventEnvelope> _envelopePool = new(capacity: 32);

public static EventEnvelope Rent()
{
    return _envelopePool.Count > 0 ? _envelopePool.Pop() : new EventEnvelope();
}

public static void Return(EventEnvelope envelope)
{
    envelope.Reset();
    _envelopePool.Push(envelope);
}
